1	package chainledger
2	
3	import (
4		"errors"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	// traceOf traces dataset in the snapshot built from graphJSON.
11	func traceOf(t *testing.T, graphJSON, dataset string) *TraceReport {
12		t.Helper()
13		report, err := TraceSources(snapshotOf(t, graphJSON), dataset)
14		if err != nil {
15			t.Fatalf("TraceSources(%q): %v", dataset, err)
16		}
17		return report
18	}
19	
20	func TestTraceDirectRootBeatsIndirect(t *testing.T) {
21		// T depends on R directly and also reaches R through B: the direct,
22		// shorter path wins.
23		report := traceOf(t, `{"datasets":[
24			{"name":"T","upstreams":["R","B"]},
25			{"name":"B","upstreams":["R"]},
26			{"name":"R","upstreams":[]}
27		]}`, "T")
28		want := []SourceTrace{{Root: "R", Path: []string{"T", "R"}}}
29		if !reflect.DeepEqual(report.Sources, want) {
30			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
31		}
32	}
33	
34	func TestTraceEqualLengthPrefersByteOrder(t *testing.T) {
35		// T reaches R through A or through B with the same number of relations;
36		// the path via the bytewise-smaller intermediate name wins.
37		report := traceOf(t, `{"datasets":[
38			{"name":"T","upstreams":["B","A"]},
39			{"name":"A","upstreams":["R"]},
40			{"name":"B","upstreams":["R"]},
41			{"name":"R","upstreams":[]}
42		]}`, "T")
43		want := []SourceTrace{{Root: "R", Path: []string{"T", "A", "R"}}}
44		if !reflect.DeepEqual(report.Sources, want) {
45			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
46		}
47	}
48	
49	func TestTraceMultipleRootsSortedAndSharedIntermediates(t *testing.T) {
50		// Two roots share the intermediate M; each keeps its own path, and the
51		// sources are sorted by root name byte order ("Z" before "a").
52		report := traceOf(t, `{"datasets":[
53			{"name":"T","upstreams":["M"]},
54			{"name":"M","upstreams":["a","Z"]},
55			{"name":"a","upstreams":[]},
56			{"name":"Z","upstreams":[]}
57		]}`, "T")
58		want := []SourceTrace{
59			{Root: "Z", Path: []string{"T", "M", "Z"}},
60			{Root: "a", Path: []string{"T", "M", "a"}},
61		}
62		if !reflect.DeepEqual(report.Sources, want) {
63			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
64		}
65	}
66	
67	func TestTraceRootQueriesItself(t *testing.T) {
68		report := traceOf(t, `{"datasets":[
69			{"name":"R","upstreams":[]},
70			{"name":"S","upstreams":["R"]}
71		]}`, "R")
72		want := []SourceTrace{{Root: "R", Path: []string{"R"}}}
73		if !reflect.DeepEqual(report.Sources, want) {
74			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
75		}
76	}
77	
78	func TestTraceIgnoresDisconnectedAndNonRootIntermediates(t *testing.T) {
79		// X is disconnected and must not appear; M has an upstream so it is not
80		// a root even though it is on the path.
81		report := traceOf(t, `{"datasets":[
82			{"name":"T","upstreams":["M"]},
83			{"name":"M","upstreams":["R"]},
84			{"name":"R","upstreams":[]},
85			{"name":"X","upstreams":[]}
86		]}`, "T")
87		want := []SourceTrace{{Root: "R", Path: []string{"T", "M", "R"}}}
88		if !reflect.DeepEqual(report.Sources, want) {
89			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
90		}
91	}
92	
93	func TestTraceReportCarriesContentIDAndQuery(t *testing.T) {
94		snap := snapshotOf(t, `{"datasets":[{"name":"T","upstreams":[]}]}`)
95		report, err := TraceSources(snap, "T")
96		if err != nil {
97			t.Fatalf("TraceSources: %v", err)
98		}
99		if report.ContentID != snap.ContentID {
100			t.Errorf("ContentID = %q, want snapshot id %q", report.ContentID, snap.ContentID)
101		}
102		if report.Dataset != "T" {
103			t.Errorf("Dataset = %q, want %q", report.Dataset, "T")
104		}
105	}
106	
107	func TestTraceUnknownAndEmptyDatasetRejected(t *testing.T) {
108		snap := snapshotOf(t, `{"datasets":[{"name":"T","upstreams":[]}]}`)
109		if _, err := TraceSources(snap, ""); !errors.Is(err, ErrInvalidArgument) {
110			t.Errorf("empty name error = %v, want ErrInvalidArgument", err)
111		}
112		if _, err := TraceSources(snap, "ghost"); !errors.Is(err, ErrNotFound) {
113			t.Errorf("unknown name error = %v, want ErrNotFound", err)
114		}
115		if _, err := TraceSources(snap, "ghost"); err == nil || !strings.Contains(err.Error(), "ghost") {
116			t.Errorf("unknown name error = %v, must name the dataset", err)
117		}
118	}
119	
120	// TestTraceDeterministicAcrossEquivalentSnapshots checks that record order,
121	// upstream order, duplicate upstreams, and JSON whitespace never change the
122	// trace report for the same query.
123	func TestTraceDeterministicAcrossEquivalentSnapshots(t *testing.T) {
124		variants := []string{
125			`{"datasets":[{"name":"T","upstreams":["A","B"]},{"name":"A","upstreams":["R"]},{"name":"B","upstreams":["R"]},{"name":"R","upstreams":[]}]}`,
126			`{ "datasets": [ {"upstreams":[],"name":"R"}, {"name":"B","upstreams":["R","R"]}, {"name":"A","upstreams":["R"]}, {"name":"T","upstreams":["B","A","B"]} ] }`,
127		}
128		var want *TraceReport
129		for i, in := range variants {
130			report := traceOf(t, in, "T")
131			if i == 0 {
132				want = report
133				continue
134			}
135			if !reflect.DeepEqual(report, want) {
136				t.Errorf("variant %d report = %+v, want %+v", i, report, want)
137			}
138		}
139	}
140	
141	// TestTraceDeepConvergingBranches fixes the tie-break when two branches pass
142	// through different intermediate datasets and merge before the root. From T
143	// to R both routes have four relations:
144	//
145	//	T -> A -> Z -> M -> R
146	//	T -> B -> C -> M -> R
147	//
148	// There is no shorter route. The choice is made at the first differing name,
149	// which is position 1: A < B, so the path through A and Z wins even though
150	// the other branch passes through C, which is bytewise smaller than Z.
151	func TestTraceDeepConvergingBranches(t *testing.T) {
152		report := traceOf(t, `{"datasets":[
153			{"name":"T","upstreams":["B","A"]},
154			{"name":"A","upstreams":["Z"]},
155			{"name":"Z","upstreams":["M"]},
156			{"name":"B","upstreams":["C"]},
157			{"name":"C","upstreams":["M"]},
158			{"name":"M","upstreams":["R"]},
159			{"name":"R","upstreams":[]}
160		]}`, "T")
161		want := []SourceTrace{{Root: "R", Path: []string{"T", "A", "Z", "M", "R"}}}
162		if !reflect.DeepEqual(report.Sources, want) {
163			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
164		}
165	}
166	
167	// TestTraceDeepSharedPrefixDivergesLate checks that equally long routes which
168	// share several first nodes are decided at the first position where they
169	// actually differ, not earlier or later. The full name array is returned:
170	// query object, every intermediate dataset, and the root.
171	func TestTraceDeepSharedPrefixDivergesLate(t *testing.T) {
172		// T -> P -> Q then either X -> M -> R or Y -> M -> R; the branches merge
173		// again at M. At the first differing position X < Y, so X's route wins
174		// even though it then climbs through the large name M.
175		report := traceOf(t, `{"datasets":[
176			{"name":"T","upstreams":["P"]},
177			{"name":"P","upstreams":["Q"]},
178			{"name":"Q","upstreams":["Y","X"]},
179			{"name":"X","upstreams":["M"]},
180			{"name":"Y","upstreams":["M"]},
181			{"name":"M","upstreams":["R"]},
182			{"name":"R","upstreams":[]}
183		]}`, "T")
184		want := []SourceTrace{{Root: "R", Path: []string{"T", "P", "Q", "X", "M", "R"}}}
185		if !reflect.DeepEqual(report.Sources, want) {
186			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
187		}
188	}
189	
190	// TestTraceShortPathBeatsSmallerNamedLongRoute fixes that the number of
191	// direct relations is decided first: the same root may also be reachable
192	// through a branch whose names are all bytewise smaller, but when that branch
193	// is one relation longer, the shorter path still represents the root.
194	func TestTraceShortPathBeatsSmallerNamedLongRoute(t *testing.T) {
195		// Short route (3 relations): T -> A -> Z -> R.
196		// Long route (4 relations): T -> 0a -> 0b -> 0c -> R; every name on it
197		// sorts below "A" because '0' (0x30) precedes 'A' (0x41) in UTF-8 bytes.
198		report := traceOf(t, `{"datasets":[
199			{"name":"T","upstreams":["0a","A"]},
200			{"name":"A","upstreams":["Z"]},
201			{"name":"Z","upstreams":["R"]},
202			{"name":"0a","upstreams":["0b"]},
203			{"name":"0b","upstreams":["0c"]},
204			{"name":"0c","upstreams":["R"]},
205			{"name":"R","upstreams":[]}
206		]}`, "T")
207		want := []SourceTrace{{Root: "R", Path: []string{"T", "A", "Z", "R"}}}
208		if !reflect.DeepEqual(report.Sources, want) {
209			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
210		}
211	}
212	
213	// TestTraceMergedIntermediateKeepsPerRootShortestPaths uses a merge node that
214	// continues to two roots. Every root keeps its own shortest path, and the
215	// merge node itself is never reported as a root because it still has
216	// upstreams.
217	func TestTraceMergedIntermediateKeepsPerRootShortestPaths(t *testing.T) {
218		// Both branches merge at M; M then reaches roots R1 and R2.
219		report := traceOf(t, `{"datasets":[
220			{"name":"T","upstreams":["B","A"]},
221			{"name":"A","upstreams":["M"]},
222			{"name":"B","upstreams":["M"]},
223			{"name":"M","upstreams":["R2","R1"]},
224			{"name":"R1","upstreams":[]},
225			{"name":"R2","upstreams":[]}
226		]}`, "T")
227		want := []SourceTrace{
228			{Root: "R1", Path: []string{"T", "A", "M", "R1"}},
229			{Root: "R2", Path: []string{"T", "A", "M", "R2"}},
230		}
231		if !reflect.DeepEqual(report.Sources, want) {
232			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
233		}
234	}
235	
236	// TestTraceShortcutToOneRootLeavesOtherRootsUntouched combines a multi-root
237	// merge with a shortcut to just one of the roots. The shortcut changes only
238	// that root's representative path; the other root is still reported with its
239	// own shortest path, and roots are ordered by root name byte order.
240	func TestTraceShortcutToOneRootLeavesOtherRootsUntouched(t *testing.T) {
241		// T -> A -> M reaches both R1 and R2 (3 relations each). T also reaches
242		// R1 directly, which shortens only R1's path to one relation.
243		report := traceOf(t, `{"datasets":[
244			{"name":"T","upstreams":["R1","A"]},
245			{"name":"A","upstreams":["M"]},
246			{"name":"M","upstreams":["R2","R1"]},
247			{"name":"R1","upstreams":[]},
248			{"name":"R2","upstreams":[]}
249		]}`, "T")
250		want := []SourceTrace{
251			{Root: "R1", Path: []string{"T", "R1"}},
252			{Root: "R2", Path: []string{"T", "A", "M", "R2"}},
253		}
254		if !reflect.DeepEqual(report.Sources, want) {
255			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
256		}
257	}
258	
259	// TestTraceRootQueriesItselfAmidDeepLineage pins the single-element result in
260	// a non-trivial graph: the queried root reports only itself, even though deep
261	// unrelated lineage exists around it.
262	func TestTraceRootQueriesItselfAmidDeepLineage(t *testing.T) {
263		report := traceOf(t, `{"datasets":[
264			{"name":"T","upstreams":["M"]},
265			{"name":"M","upstreams":["R"]},
266			{"name":"R","upstreams":[]}
267		]}`, "R")
268		want := []SourceTrace{{Root: "R", Path: []string{"R"}}}
269		if !reflect.DeepEqual(report.Sources, want) {
270			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
271		}
272	}
273	
274	// TestTraceDeepLineageIgnoresDisconnectedBranches ensures branches that do
275	// not connect to the queried dataset — including a second deep diamond with
276	// its own roots — never appear among the sources or change path selection.
277	func TestTraceDeepLineageIgnoresDisconnectedBranches(t *testing.T) {
278		report := traceOf(t, `{"datasets":[
279			{"name":"T","upstreams":["A"]},
280			{"name":"A","upstreams":["M"]},
281			{"name":"M","upstreams":["R"]},
282			{"name":"R","upstreams":[]},
283			{"name":"U","upstreams":["C","B"]},
284			{"name":"B","upstreams":["N"]},
285			{"name":"C","upstreams":["N"]},
286			{"name":"N","upstreams":["X"]},
287			{"name":"X","upstreams":[]}
288		]}`, "T")
289		want := []SourceTrace{{Root: "R", Path: []string{"T", "A", "M", "R"}}}
290		if !reflect.DeepEqual(report.Sources, want) {
291			t.Errorf("Sources = %+v, want %+v", report.Sources, want)
292		}
293	}
294	
295	// TestTraceDeterministicAcrossEquivalentDeepSnapshots is the deep version of
296	// the determinism guarantee: record order, upstream order, duplicate
297	// upstreams, and whitespace reshuffle a graph with converging branches and
298	// multiple post-merge roots, yet every path choice stays identical.
299	func TestTraceDeterministicAcrossEquivalentDeepSnapshots(t *testing.T) {
300		variants := []string{
301			// Canonical-ish order: T with two branches merging at M, M reaching
302			// two roots, plus a disconnected branch.
303			`{"datasets":[
304				{"name":"T","upstreams":["B","A"]},
305				{"name":"A","upstreams":["Z"]},
306				{"name":"Z","upstreams":["M"]},
307				{"name":"B","upstreams":["C"]},
308				{"name":"C","upstreams":["M"]},
309				{"name":"M","upstreams":["R2","R1"]},
310				{"name":"R1","upstreams":[]},
311				{"name":"R2","upstreams":[]},
312				{"name":"U","upstreams":["X"]},
313				{"name":"X","upstreams":[]}
314			]}`,
315			// Same semantics: records reversed, upstream lists reordered with
316			// duplicates, whitespace changed.
317			`{ "datasets" : [
318				{"upstreams":[],"name":"X"},
319				{"name":"U","upstreams":["X","X"]},
320				{"upstreams":[],"name":"R2"},
321				{"name":"R1","upstreams":[]},
322				{"upstreams":["R1","R2","R1"],"name":"M"},
323				{"name":"C","upstreams":["M","M"]},
324				{"upstreams":["M"],"name":"Z"},
325				{"name":"B","upstreams":["C"]},
326				{"name":"A","upstreams":["Z"]},
327				{"upstreams":["A","B","B","A"],"name":"T"}
328			] }`,
329		}
330		var want *TraceReport
331		for i, in := range variants {
332			report := traceOf(t, in, "T")
333			if i == 0 {
334				want = report
335				continue
336			}
337			if !reflect.DeepEqual(report, want) {
338				t.Errorf("variant %d report = %+v, want %+v", i, report, want)
339			}
340		}
341		// Pin the expected choice once so the determinism check cannot pass while
342		// both variants make the same wrong selection.
343		wantSources := []SourceTrace{
344			{Root: "R1", Path: []string{"T", "A", "Z", "M", "R1"}},
345			{Root: "R2", Path: []string{"T", "A", "Z", "M", "R2"}},
346		}
347		if !reflect.DeepEqual(want.Sources, wantSources) {
348			t.Errorf("Sources = %+v, want %+v", want.Sources, wantSources)
349		}
350		if want.ContentID == "" || want.Dataset != "T" {
351			t.Errorf("report metadata = contentId %q dataset %q, want snapshot id and %q", want.ContentID, want.Dataset, "T")
352		}
353	}
354	
355	// TestTraceReportCarriesContentIDAndQueryDeep pins, for a deep graph, that
356	// the report's identifiers come from the snapshot actually read and from the
357	// query as typed — never from whichever input record appeared first.
358	func TestTraceReportCarriesContentIDAndQueryDeep(t *testing.T) {
359		in := `{"datasets":[
360			{"name":"R","upstreams":[]},
361			{"name":"M","upstreams":["R"]},
362			{"name":"Z","upstreams":["M"]},
363			{"name":"A","upstreams":["Z"]},
