370		}
371		if report.ContentID != snap.ContentID {
372			t.Errorf("ContentID = %q, want %q", report.ContentID, snap.ContentID)
373		}
374		if report.Dataset != "T" {
375			t.Errorf("Dataset = %q, want %q", report.Dataset, "T")
376		}
