1	package chainledger
2	
3	import (
4		"bytes"
5		"errors"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// This file pins the content independence of lineage snapshots returned by
12	// BuildSnapshot. A caller that builds a snapshot from the in-memory graph keeps
13	// holding the original map and may hold several snapshots of the same graph at
14	// once. Every returned snapshot must freeze the datasets and direct upstreams
15	// as they were when BuildSnapshot returned:
16	//
17	//   - editing the original graph afterwards (replacing an upstream name in
18	//     place, appending to a stored list, removing a node) must not move an
19	//     already returned snapshot's content identifier or its full export bytes,
20	//     which must still parse under the existing reader rules with an id
21	//     matching the embedded graph;
22	//   - editing one returned snapshot's records (an upstream record or a dataset
23	//     record) must not reach another snapshot of the same graph, nor the
24	//     graph — including two dataset records that started with identical
25	//     upstream lists, which must own separate backing arrays;
26	//   - BuildSnapshot itself stays read-only: the graph keeps its submitted
27	//     upstream order and duplicates, while the snapshot sorts and deduplicates
28	//     by the existing rules, roots export "upstreams": [], and an empty graph
29	//     exports "datasets": [];
30	//   - a snapshot taken before the graph gained a missing upstream still
31	//     exports, while building again from the now-corrupt graph fails by the
32	//     existing rules, returns no usable snapshot, and changes nothing.
33	//
34	// The deliberately corrupted copy a caller edits for display is out of scope:
35	// nothing repairs it or recomputes its content identifier.
36	
37	// mustMarshalSnapshot renders a snapshot the way every caller exports it,
38	// failing the test on an impossible-on-valid-input error.
39	func mustMarshalSnapshot(t *testing.T, snap *SnapshotFile) []byte {
40		t.Helper()
41		data, err := MarshalSnapshot(snap)
42		if err != nil {
43			t.Fatalf("MarshalSnapshot unexpected error: %v", err)
44		}
45		return data
46	}
47	
48	// snapshotDatasetIndex returns the index of name's record in snap, or -1.
49	func snapshotDatasetIndex(snap *SnapshotFile, name string) int {
50		for i := range snap.Graph.Datasets {
51			if snap.Graph.Datasets[i].Name == name {
52				return i
53			}
54		}
55		return -1
56	}
57	
58	// mustSnapshotDataset returns a value copy of name's record in snap.
59	func mustSnapshotDataset(t *testing.T, snap *SnapshotFile, name string) GraphDataset {
60		t.Helper()
61		if i := snapshotDatasetIndex(snap, name); i >= 0 {
62			return snap.Graph.Datasets[i]
63		}
64		t.Fatalf("snapshot has no dataset record %q", name)
65		return GraphDataset{}
66	}
67	
68	// independentDiamondGraph builds the headline shape: two roots A and R, an
69	// intermediate M that depends on BOTH roots, and a downstream D depending on
70	// M. Register leaves every stored Parents list already sorted and
71	// duplicate-free, which is the tempting shortcut case for an implementation
72	// that could hand the graph's own slice to the snapshot.
73	func independentDiamondGraph(t *testing.T) map[string]*Lineage {
74		t.Helper()
75		return buildGraph(t, P("A"), P("R"), P("M", "A", "R"), P("D", "M"))
76	}
77	
78	// TestSnapshotFreezesContentWhenGraphEditedAfterward is the headline
79	// independence guarantee: after the caller edits the original graph in place
80	// (replacing a name inside an existing upstream list, appending a ghost
81	// upstream, and removing a node), the old snapshot still holds every original
82	// node and edge, with the same content identifier and byte-identical export,
83	// and those bytes still read back as a legal snapshot whose id matches its
84	// graph.
85	func TestSnapshotFreezesContentWhenGraphEditedAfterward(t *testing.T) {
86		graph := independentDiamondGraph(t)
87		snap, err := BuildSnapshot(graph)
88		if err != nil {
89			t.Fatalf("BuildSnapshot unexpected error: %v", err)
90		}
91		wantID := snap.ContentID
92		wantBytes := mustMarshalSnapshot(t, snap)
93	
94		// Edit the original graph as a caller holding it might: overwrite a parent
95		// name inside the existing backing array, append into it, and delete a
96		// node the frozen snapshot must still contain. The graph is now corrupt
97		// (M references missing upstreams), which is exactly why the frozen copy
98		// must not read through to it.
99		graph["M"].Parents[0] = "HACK"
100		graph["M"].Parents = append(graph["M"].Parents, "ghost")
101		delete(graph, "R")
102	
103		// Sanity: the edits really landed on the graph.
104		if _, present := graph["R"]; present {
105			t.Fatalf("test setup: node R still present in the original graph")
106		}
107		if got := graph["M"].Parents; reflect.DeepEqual(got, []string{"A", "R"}) {
108			t.Fatalf("test setup: M.Parents was not edited: %v", got)
109		}
110	
111		if got := snap.ContentID; got != wantID {
112			t.Errorf("snapshot content id moved with the graph: %s, want %s", got, wantID)
113		}
114		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, wantBytes) {
115			t.Errorf("snapshot export moved with the graph:\n got %s\nwant %s", got, wantBytes)
116		}
117	
118		// The frozen export still obeys every existing reader rule, including the
119		// check that the content id matches the embedded graph.
120		parsed, err := ParseSnapshot(wantBytes)
121		if err != nil {
122			t.Fatalf("frozen snapshot no longer parses after the graph was edited: %v", err)
123		}
124		if parsed.ContentID != wantID {
125			t.Errorf("parsed content id = %s, want %s", parsed.ContentID, wantID)
126		}
127		if !reflect.DeepEqual(parsed, snap) {
128			t.Errorf("parsed snapshot differs from the returned snapshot:\n got %#v\nwant %#v", parsed, snap)
129		}
130	
131		// All four original nodes and every original edge survive.
132		if got := len(snap.Graph.Datasets); got != 4 {
133			t.Errorf("frozen snapshot has %d datasets, want 4: %+v", got, snap.Graph.Datasets)
134		}
135		if got := mustSnapshotDataset(t, snap, "R").Upstreams; !reflect.DeepEqual(got, []string{}) {
136			t.Errorf("removed root R not frozen with empty upstreams: %v", got)
137		}
138		if got := mustSnapshotDataset(t, snap, "M").Upstreams; !reflect.DeepEqual(got, []string{"A", "R"}) {
139			t.Errorf("M.upstreams = %v, want frozen [A R]", got)
140		}
141		if got := mustSnapshotDataset(t, snap, "D").Upstreams; !reflect.DeepEqual(got, []string{"M"}) {
142			t.Errorf("D.upstreams = %v, want frozen [M]", got)
143		}
144		if got := mustSnapshotDataset(t, snap, "A").Upstreams; !reflect.DeepEqual(got, []string{}) {
145			t.Errorf("A.upstreams = %v, want frozen empty list", got)
146		}
147		// The frozen graph's lineage still resolves D to both original roots.
148		if got := rootSources("D", adjacencyFromValidFile(snap.Graph)); !reflect.DeepEqual(got, []string{"A", "R"}) {
149			t.Errorf("frozen D roots = %v, want [A R]", got)
150		}
151	}
152	
153	// TestSnapshotBuildIsReadOnly pins the read-only build: shuffled and repeated
154	// upstreams in the submitted graph stay verbatim there, while the snapshot
155	// normalizes by the existing sorting and de-duplication rules, roots carry a
156	// non-nil empty upstream list, and an empty graph exports "datasets": [].
157	func TestSnapshotBuildIsReadOnly(t *testing.T) {
158		// Built by hand on purpose: Register would already normalize Parents, but
159		// BuildSnapshot must tolerate and preserve any stored spelling.
160		graph := map[string]*Lineage{
161			"A": {Dataset: "A"},
162			"R": {Dataset: "R"},
163			"M": {Dataset: "M", Parents: []string{"R", "A", "R"}},
164			"D": {Dataset: "D", Parents: []string{"M", "M"}},
165		}
166		snap, err := BuildSnapshot(graph)
167		if err != nil {
168			t.Fatalf("BuildSnapshot unexpected error: %v", err)
169		}
170	
171		// The original graph keeps its submitted order, duplicates, and untouched
172		// derived fields (BuildSnapshot never maintains Children).
173		if got := graph["M"].Parents; !reflect.DeepEqual(got, []string{"R", "A", "R"}) {
174			t.Errorf("BuildSnapshot reordered/deduped M.Parents: %v, want verbatim [R A R]", got)
175		}
176		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"M", "M"}) {
177			t.Errorf("BuildSnapshot deduped D.Parents: %v, want verbatim [M M]", got)
178		}
179		if got := graph["A"].Children; got != nil {
180			t.Errorf("BuildSnapshot wrote derived Children on a root: %v", got)
181		}
182	
183		// The snapshot side is normalized instead: records sorted by name and
184		// upstreams sorted and duplicate-free.
185		wantNames := []string{"A", "D", "M", "R"}
186		gotNames := make([]string, 0, len(snap.Graph.Datasets))
187		for _, ds := range snap.Graph.Datasets {
188			gotNames = append(gotNames, ds.Name)
189		}
190		if !reflect.DeepEqual(gotNames, wantNames) {
191			t.Errorf("snapshot dataset order = %v, want %v", gotNames, wantNames)
192		}
193		if got := mustSnapshotDataset(t, snap, "M").Upstreams; !reflect.DeepEqual(got, []string{"A", "R"}) {
194			t.Errorf("snapshot M.upstreams = %v, want sorted/deduped [A R]", got)
195		}
196		if got := mustSnapshotDataset(t, snap, "D").Upstreams; !reflect.DeepEqual(got, []string{"M"}) {
197			t.Errorf("snapshot D.upstreams = %v, want deduped [M]", got)
198		}
199		for _, name := range []string{"A", "R"} {
200			got := mustSnapshotDataset(t, snap, name).Upstreams
201			if got == nil || len(got) != 0 {
202				t.Errorf("root %s upstreams = %v, want non-nil empty list", name, got)
203			}
204		}
205		if data := mustMarshalSnapshot(t, snap); !strings.Contains(string(data), `"upstreams": []`) {
206			t.Errorf("root upstreams not exported as an empty array:\n%s", data)
207		}
208	
209		// An empty graph is legal and exports datasets as an empty array.
210		empty, err := BuildSnapshot(map[string]*Lineage{})
211		if err != nil {
212			t.Fatalf("BuildSnapshot(empty) unexpected error: %v", err)
213		}
214		if len(empty.Graph.Datasets) != 0 {
215			t.Errorf("empty graph produced datasets %v", empty.Graph.Datasets)
216		}
217		if data := mustMarshalSnapshot(t, empty); !strings.Contains(string(data), `"datasets": []`) {
218			t.Errorf("empty graph datasets not exported as []:\n%s", data)
219		}
220	}
221	
222	// TestTwoSnapshotsOfSameGraphAreIndependent verifies that two snapshots
223	// returned separately from one graph start out identical (same content id and
224	// export bytes), but editing an upstream record or a dataset record in one
225	// copy leaves the other copy and the original graph untouched.
226	func TestTwoSnapshotsOfSameGraphAreIndependent(t *testing.T) {
227		graph := independentDiamondGraph(t)
228		first, err := BuildSnapshot(graph)
229		if err != nil {
230			t.Fatalf("first BuildSnapshot unexpected error: %v", err)
231		}
232		second, err := BuildSnapshot(graph)
233		if err != nil {
234			t.Fatalf("second BuildSnapshot unexpected error: %v", err)
235		}
236		// An independently built reference describing the same frozen graph.
237		reference, err := BuildSnapshot(independentDiamondGraph(t))
238		if err != nil {
239			t.Fatalf("reference BuildSnapshot unexpected error: %v", err)
240		}
241	
242		if first.ContentID != second.ContentID {
243			t.Fatalf("initial content ids differ: %s vs %s", first.ContentID, second.ContentID)
244		}
245		if got, want := mustMarshalSnapshot(t, first), mustMarshalSnapshot(t, second); !bytes.Equal(got, want) {
246			t.Fatalf("initial export bytes differ:\n%s\n%s", got, want)
247		}
248	
249		graphDumpBefore := dump(graph)
250	
251		// Corrupt the first returned snapshot for display: rewrite an upstream in
252		// place, append into the same backing array, and change a dataset record's
253		// name.
254		iM := snapshotDatasetIndex(first, "M")
255		if iM < 0 {
256			t.Fatalf("first snapshot missing M")
257		}
258		first.Graph.Datasets[iM].Upstreams[0] = "HACK"
259		first.Graph.Datasets[iM].Upstreams = append(first.Graph.Datasets[iM].Upstreams, "ghost")
260		iD := snapshotDatasetIndex(first, "D")
261		if iD < 0 {
262			t.Fatalf("first snapshot missing D")
263		}
264		first.Graph.Datasets[iD].Name = "DISPLAY"
265	
266		// Sanity: the local edit really happened on the first copy.
267		if got := first.Graph.Datasets[iM].Upstreams; reflect.DeepEqual(got, []string{"A", "R"}) {
268			t.Fatalf("test setup: editing the first snapshot had no local effect: %v", got)
269		}
270	
271		// The second snapshot is byte-for-byte the original frozen graph.
272		if got := second.ContentID; got != reference.ContentID {
273			t.Errorf("second snapshot content id = %s, want %s", got, reference.ContentID)
274		}
275		if got, want := mustMarshalSnapshot(t, second), mustMarshalSnapshot(t, reference); !bytes.Equal(got, want) {
276			t.Errorf("second snapshot export changed:\n got %s\nwant %s", got, want)
277		}
278		if !reflect.DeepEqual(second.Graph, reference.Graph) {
279			t.Errorf("second snapshot graph = %#v, want %#v", second.Graph, reference.Graph)
280		}
281		if got := mustSnapshotDataset(t, second, "M").Upstreams; !reflect.DeepEqual(got, []string{"A", "R"}) {
282			t.Errorf("second snapshot M.upstreams = %v, want untouched [A R]", got)
283		}
284		if got := mustSnapshotDataset(t, second, "D"); got.Name != "D" || !reflect.DeepEqual(got.Upstreams, []string{"M"}) {
285			t.Errorf("second snapshot D record changed: %#v", got)
286		}
287	
288		// The original graph is untouched as well.
289		if got := dump(graph); got != graphDumpBefore {
290			t.Errorf("editing a snapshot mutated the original graph:\n got %s\nwant %s", got, graphDumpBefore)
291		}
292		if got := graph["M"].Parents; !reflect.DeepEqual(got, []string{"A", "R"}) {
293			t.Errorf("graph M.Parents = %v, want untouched [A R]", got)
294		}
295		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"M"}) {
296			t.Errorf("graph D.Parents = %v, want untouched [M]", got)
297		}
298	}
299	
300	// TestSnapshotSharedUpstreamRecordsAreIndependent verifies that when two
301	// datasets are frozen with the same direct-upstream list, each snapshot record
302	// owns that list: editing one record (in place and via append) must not drag
303	// the other record — in either the snapshot or the original graph.
304	func TestSnapshotSharedUpstreamRecordsAreIndependent(t *testing.T) {
305		// Two roots; both M and N derive from both; a downstream keeps M used.
306		graph := buildGraph(t, P("A"), P("R"), P("M", "A", "R"), P("N", "R", "A"), P("D", "M"))
307		snap, err := BuildSnapshot(graph)
308		if err != nil {
309			t.Fatalf("BuildSnapshot unexpected error: %v", err)
310		}
311		if got := mustSnapshotDataset(t, snap, "M").Upstreams; !reflect.DeepEqual(got, []string{"A", "R"}) {
312			t.Fatalf("test setup: M.upstreams = %v, want [A R]", got)
313		}
314		if got := mustSnapshotDataset(t, snap, "N").Upstreams; !reflect.DeepEqual(got, []string{"A", "R"}) {
315			t.Fatalf("test setup: N.upstreams = %v, want [A R]", got)
316		}
317	
318		// Edit only M's frozen record, both by overwriting in place and by
319		// appending into its backing array.
320		iM := snapshotDatasetIndex(snap, "M")
321		snap.Graph.Datasets[iM].Upstreams[0] = "X"
322		snap.Graph.Datasets[iM].Upstreams = append(snap.Graph.Datasets[iM].Upstreams, "Y")
323	
324		if got := mustSnapshotDataset(t, snap, "N").Upstreams; !reflect.DeepEqual(got, []string{"A", "R"}) {
325			t.Errorf("N.upstreams = %v, want untouched [A R] after editing M's record", got)
326		}
327		if got := mustSnapshotDataset(t, snap, "D").Upstreams; !reflect.DeepEqual(got, []string{"M"}) {
328			t.Errorf("D.upstreams = %v, want untouched [M]", got)
329		}
330		if got := graph["N"].Parents; !reflect.DeepEqual(got, []string{"A", "R"}) {
331			t.Errorf("graph N.Parents = %v, want untouched [A R]", got)
332		}
333		if got := graph["M"].Parents; !reflect.DeepEqual(got, []string{"A", "R"}) {
334			t.Errorf("graph M.Parents = %v, want untouched [A R]", got)
335		}
336	}
337	
338	// TestOldSnapshotExportsAfterGraphCorruptsRebuildFails verifies the boundary
339	// around a graph that becomes invalid after a snapshot was taken: the existing
340	// legal snapshot still exports and parses unchanged, while building again from
341	// the corrupt graph fails by the existing rules, returns no usable snapshot,
342	// and mutates neither the graph nor the previously saved snapshot.
343	func TestOldSnapshotExportsAfterGraphCorruptsRebuildFails(t *testing.T) {
344		cases := map[string]struct {
345			corrupt  func(map[string]*Lineage)
346			wantErr  error
347			checkErr func(error) bool
348		}{
349			"missing upstream": {
350				corrupt: func(g map[string]*Lineage) { g["B"].Parents = []string{"ghost"} },
351				wantErr: ErrNotFound,
352			},
353			"cycle introduced": {
354				corrupt: func(g map[string]*Lineage) { g["A"].Parents = []string{"B"} },
355				wantErr: ErrCycle,
356			},
357		}
358		for name, tc := range cases {
359			t.Run(name, func(t *testing.T) {
360				graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
361				old, err := BuildSnapshot(graph)
362				if err != nil {
363					t.Fatalf("initial BuildSnapshot unexpected error: %v", err)
364				}
365				wantID := old.ContentID
366				wantBytes := mustMarshalSnapshot(t, old)
367	
368				tc.corrupt(graph)
369				graphDumpAfterCorruption := dump(graph)
370	
371				bad, err := BuildSnapshot(graph)
372				if !errors.Is(err, tc.wantErr) {
373					t.Fatalf("BuildSnapshot on corrupt graph err = %v, want %v", err, tc.wantErr)
374				}
375				if bad != nil {
376					t.Fatalf("failed build returned a usable snapshot: %#v", bad)
377				}
378	
379				// The failed build changed nothing: the corrupt graph is as the
380				// caller left it and the old snapshot is byte-for-byte intact.
381				if got := dump(graph); got != graphDumpAfterCorruption {
382					t.Errorf("failed build mutated the graph:\n got %s\nwant %s", got, graphDumpAfterCorruption)
383				}
384				if got := old.ContentID; got != wantID {
385					t.Errorf("old snapshot content id = %s, want %s", got, wantID)
386				}
387				if got := mustMarshalSnapshot(t, old); !bytes.Equal(got, wantBytes) {
388					t.Errorf("old snapshot export changed:\n got %s\nwant %s", got, wantBytes)
389				}
390				parsed, err := ParseSnapshot(wantBytes)
391				if err != nil {
392					t.Fatalf("old snapshot no longer parses: %v", err)
393				}
394				if parsed.ContentID != wantID {
395					t.Errorf("parsed old snapshot id = %s, want %s", parsed.ContentID, wantID)
396				}
397			})
398		}
399	}
400	
401	// TestSnapshotPreservesNameCaseAndWhitespace verifies that the frozen records
402	// keep dataset and upstream names verbatim: casing and surrounding spaces
403	// still distinguish datasets, and the distinction survives the full export
404	// and re-read.
405	func TestSnapshotPreservesNameCaseAndWhitespace(t *testing.T) {
406		// "A", "a", and " A " are three different datasets; M derives from the
407		// two space/case-variant roots.
408		graph := buildGraph(t, P("A"), P("a"), P(" A "), P("M", " A ", "a"))
409		snap, err := BuildSnapshot(graph)
410		if err != nil {
411			t.Fatalf("BuildSnapshot unexpected error: %v", err)
412		}
413	
414		// Byte order sorts " A " (0x20) before "A" (0x41) before "M" before "a"
415		// (0x61); the point here is not the exact order but that every spelling
416		// survives as its own record.
417		names := map[string]bool{}
418		for _, ds := range snap.Graph.Datasets {
419			names[ds.Name] = true
420		}
421		for _, want := range []string{"A", "a", " A ", "M"} {
422			if !names[want] {
423				t.Errorf("snapshot lost or rewrote dataset name %q; records: %v", want, names)
424			}
425		}
426		if got := mustSnapshotDataset(t, snap, "M").Upstreams; !reflect.DeepEqual(got, []string{" A ", "a"}) {
427			t.Errorf("M.upstreams = %v, want verbatim [\" A \" \"a\"]", got)
428		}
429	
430		data := mustMarshalSnapshot(t, snap)
431		// The space-wrapped name must appear verbatim in the export, never trimmed.
432		if !bytes.Contains(data, []byte(`" A "`)) {
433			t.Errorf("export does not preserve the space-wrapped name:\n%s", data)
434		}
435		parsed, err := ParseSnapshot(data)
436		if err != nil {
437			t.Fatalf("name-variant snapshot failed to parse: %v", err)
438		}
439		if parsed.ContentID != snap.ContentID {
440			t.Errorf("parsed content id = %s, want %s", parsed.ContentID, snap.ContentID)
441		}
442		if !reflect.DeepEqual(parsed.Graph, snap.Graph) {
443			t.Errorf("parsed graph differs: %#v\nwant %#v", parsed.Graph, snap.Graph)
444		}
445	
446		// Editing the original graph afterwards still cannot rename a frozen node.
447		graph["M"].Parents[0] = "trimmed"
448		if got := mustSnapshotDataset(t, snap, "M").Upstreams; !reflect.DeepEqual(got, []string{" A ", "a"}) {
449			t.Errorf("frozen M.upstreams followed a graph edit: %v", got)
450		}
451	}
