281	func TestRegisterErrorCases(t *testing.T) {
282		t.Run("empty dataset name", func(t *testing.T) {
283			graph := map[string]*Lineage{}
284			err := Register(graph, Dataset{Name: ""}, nil)
285			if !errors.Is(err, ErrInvalidArgument) {
286				t.Fatalf("err = %v, want ErrInvalidArgument", err)
287			}
288			if len(graph) != 0 {
