1	package chainledger
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"reflect"
8		"testing"
9	)
10	
11	// This file pins the report-independence contract of TraceSources. A caller
12	// that edits a returned report for presentation must only ever move its own
13	// copy:
14	//
15	//   - replacing the queried name, an intermediate name, or the root name on
16	//     one source record, or appending a name to that path, must change only
17	//     the record being edited — even when the two paths share a prefix;
18	//   - renaming a source's root, reordering the sources array, or removing a
19	//     source from it must never reach the input snapshot's dataset names or
20	//     direct upstream relationships;
21	//
22	// Two reports taken from one snapshot (possibly of two downstreams passing
23	// through the same intermediate dataset) own their slices independently; a
24	// re-query after edits still returns the snapshot's original sources and
25	// paths with the correct content identifier and queried name. A root query's
26	// single-element path owns the same independence. Failed follow-up queries
27	// (empty or unknown name) keep the existing error categories, produce no
28	// success report, and leave prior reports and the snapshot untouched.
29	//
30	// The independence-bearing reports must still obey the existing business
31	// rules: every root appears exactly once, the path with the fewest direct
32	// relations is chosen, ties are broken element by element from the query end
33	// in UTF-8 byte order, sources are sorted by root name, names keep their
34	// Chinese characters, casing, and surrounding spaces verbatim, and the path
35	// is the array from the queried dataset to the root including both ends.
36	
37	// traceSharedIntermediateJSON is the headline shape: downstream D and the
38	// second downstream E reach two roots through their own prefix datasets and
39	// then the SAME intermediate M:
40	//
41	//	D -> P -> M -> {R1,R2}
42	//	E -> Q -> M -> {R1,R2}
43	//
44	// D's two paths share the prefix [D P M] and diverge only at the root. At
45	// four names each, a careless append-based builder would grow both paths in
46	// the same backing array (the [D P M] slice is allocated with room for one
47	// more name), so the two records are the tempting aliasing case.
48	const traceSharedIntermediateJSON = `{"datasets":[
49		{"name":"D","upstreams":["P"]},
50		{"name":"E","upstreams":["Q"]},
51		{"name":"P","upstreams":["M"]},
52		{"name":"Q","upstreams":["M"]},
53		{"name":"M","upstreams":["R2","R1"]},
54		{"name":"R1","upstreams":[]},
55		{"name":"R2","upstreams":[]}
56	]}`
57	
58	// traceSharedIntermediate builds the same graph in memory, for checks that
59	// also compare against a live graph frozen before any caller-side edits.
60	func traceSharedIntermediate(t *testing.T) map[string]*Lineage {
61		t.Helper()
62		return buildGraph(t,
63			P("R1"), P("R2"),
64			P("M", "R1", "R2"),
65			P("P", "M"), P("Q", "M"),
66			P("D", "P"), P("E", "Q"),
67		)
68	}
69	
70	// traceReportJSON renders a trace report the way a caller displaying it
71	// would, failing the test on an impossible-on-valid-input error.
72	func traceReportJSON(t *testing.T, r *TraceReport) []byte {
73		t.Helper()
74		b, err := json.Marshal(r)
75		if err != nil {
76			t.Fatalf("json.Marshal trace report unexpected error: %v", err)
77		}
78		return b
79	}
80	
81	// sourceByRoot returns the source record whose Root equals root, or nil if
82	// absent (a reorder/remove test can legitimately remove it).
83	func sourceByRoot(r *TraceReport, root string) *SourceTrace {
84		for i := range r.Sources {
85			if r.Sources[i].Root == root {
86				return &r.Sources[i]
87			}
88		}
89		return nil
90	}
91	
92	// TestTraceEditingOnePathLeavesOtherPathAndSnapshotUntouched is the headline
93	// independence guarantee: on a report whose two paths share a prefix, every
94	// kind of edit a caller might make on one path — overwrite the queried name,
95	// overwrite the shared intermediate name, overwrite the root name, and
96	// append onto that path — changes only that one record. The other source
97	// keeps its original root and complete path, and the input snapshot's
98	// dataset names and direct upstreams do not move.
99	func TestTraceEditingOnePathLeavesOtherPathAndSnapshotUntouched(t *testing.T) {
100		snap := snapshotOf(t, traceSharedIntermediateJSON)
101		wantGraph := snap.Graph
102		wantID := snap.ContentID
103		wantBytes := mustMarshalSnapshot(t, snap)
104	
105		for _, tc := range []struct {
106			name   string
107			edit   func(r *TraceReport)
108			edited func(r *TraceReport) SourceTrace
109		}{
110			{
111				name: "replace queried name on R1 path",
112				edit: func(r *TraceReport) {
113					sourceByRoot(r, "R1").Path[0] = "QUERY-X"
114				},
115				edited: func(r *TraceReport) SourceTrace {
116					return SourceTrace{Root: "R1", Path: []string{"QUERY-X", "P", "M", "R1"}}
117				},
118			},
119			{
120				name: "replace shared intermediate name on R1 path",
121				edit: func(r *TraceReport) {
122					sourceByRoot(r, "R1").Path[1] = "MID-X"
123				},
124				edited: func(r *TraceReport) SourceTrace {
125					return SourceTrace{Root: "R1", Path: []string{"D", "MID-X", "M", "R1"}}
126				},
127			},
128			{
129				name: "replace root name of R1 record",
130				edit: func(r *TraceReport) {
131					sourceByRoot(r, "R1").Root = "ROOT-X"
132				},
133				edited: func(r *TraceReport) SourceTrace {
134					return SourceTrace{Root: "ROOT-X", Path: []string{"D", "P", "M", "R1"}}
135				},
136			},
137			{
138				name: "append a name to the R1 path",
139				edit: func(r *TraceReport) {
140					s := sourceByRoot(r, "R1")
141					s.Path = append(s.Path, "TAIL-X")
142				},
143				edited: func(r *TraceReport) SourceTrace {
144					return SourceTrace{Root: "R1", Path: []string{"D", "P", "M", "R1", "TAIL-X"}}
145				},
146			},
147		} {
148			t.Run(tc.name, func(t *testing.T) {
149				report, err := TraceSources(snap, "D")
150				if err != nil {
151					t.Fatalf("TraceSources: %v", err)
152				}
153				wantSources := []SourceTrace{
154					{Root: "R1", Path: []string{"D", "P", "M", "R1"}},
155					{Root: "R2", Path: []string{"D", "P", "M", "R2"}},
156				}
157				if !reflect.DeepEqual(report.Sources, wantSources) {
158					t.Fatalf("Sources = %+v, want %+v", report.Sources, wantSources)
159				}
160	
161				tc.edit(report)
162	
163				// The other source record keeps its original root and COMPLETE
164				// original path, even though both paths started [D M].
165				if got := sourceByRoot(report, "R2"); got == nil {
166					t.Fatalf("R2 source vanished after editing the R1 record")
167				} else if want := (SourceTrace{Root: "R2", Path: []string{"D", "P", "M", "R2"}}); !reflect.DeepEqual(*got, want) {
168					t.Errorf("R2 record = %+v, want untouched %+v", *got, want)
169				}
170				// The edited record is exactly the caller's edit.
171				editedRec := SourceTrace{}
172				for _, s := range report.Sources {
173					if s.Root == tc.edited(report).Root {
174						editedRec = s
175					}
176				}
177				if want := tc.edited(report); !reflect.DeepEqual(editedRec, want) {
178					t.Errorf("edited record = %+v, want %+v", editedRec, want)
179				}
180	
181				// The input snapshot did not follow the edit: same content id,
182				// same graph, same export bytes.
183				if got := snap.ContentID; got != wantID {
184					t.Errorf("snapshot content id moved: %q, want %q", got, wantID)
185				}
186				if !reflect.DeepEqual(snap.Graph, wantGraph) {
187					t.Errorf("snapshot graph moved:\n got %#v\nwant %#v", snap.Graph, wantGraph)
188				}
189				if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, wantBytes) {
190					t.Errorf("snapshot export moved:\n got %s\nwant %s", got, wantBytes)
191				}
192				if got := mustSnapshotDataset(t, snap, "M").Upstreams; !reflect.DeepEqual(got, []string{"R1", "R2"}) {
193					t.Errorf("snapshot M.upstreams = %v, want frozen [R1 R2]", got)
194				}
195				if got := mustSnapshotDataset(t, snap, "D").Upstreams; !reflect.DeepEqual(got, []string{"M"}) {
196					t.Errorf("snapshot D.upstreams = %v, want frozen [M]", got)
197				}
198			})
199		}
200	}
201	
202	// TestTraceEditingSourceMetadataLeavesSnapshotAndOtherPathsUntouched covers
203	// the array-level edits: rename a source's root in place, swap the sources
204	// order, and remove one source. None of these may move the snapshot's
205	// dataset names or direct upstreams, and the surviving record keeps its full
206	// path even after a backing-array reorder.
207	func TestTraceEditingSourceMetadataLeavesSnapshotAndOtherPathsUntouched(t *testing.T) {
208		for _, tc := range []struct {
209			name string
210			edit func(r *TraceReport)
211			// remaining maps the surviving roots to their expected full paths.
212			remaining map[string][]string
213		}{
214			{
215				name: "rename R1 root in place",
216				edit: func(r *TraceReport) { sourceByRoot(r, "R1").Root = "HACK" },
217				remaining: map[string][]string{
218					"HACK": {"D", "P", "M", "R1"},
219					"R2":   {"D", "P", "M", "R2"},
220				},
221			},
222			{
223				name: "reorder sources array",
224				edit: func(r *TraceReport) {
225					r.Sources[0], r.Sources[1] = r.Sources[1], r.Sources[0]
226				},
227				remaining: map[string][]string{
228					"R1": {"D", "P", "M", "R1"},
229					"R2": {"D", "P", "M", "R2"},
230				},
231			},
232			{
233				name: "remove one source",
234				edit: func(r *TraceReport) {
235					r.Sources = r.Sources[:1]
236				},
237				remaining: map[string][]string{
238					"R1": {"D", "P", "M", "R1"},
239				},
240			},
241		} {
242			t.Run(tc.name, func(t *testing.T) {
243				snap := snapshotOf(t, traceSharedIntermediateJSON)
244				wantGraph := snap.Graph
245				wantID := snap.ContentID
246				wantBytes := mustMarshalSnapshot(t, snap)
247	
248				report, err := TraceSources(snap, "D")
249				if err != nil {
250					t.Fatalf("TraceSources: %v", err)
251				}
252				tc.edit(report)
253	
254				if len(report.Sources) != len(tc.remaining) {
255					t.Fatalf("sources count = %d, want %d: %+v", len(report.Sources), len(tc.remaining), report.Sources)
256				}
257				for _, s := range report.Sources {
258					wantPath, ok := tc.remaining[s.Root]
259					if !ok {
260						t.Errorf("unexpected surviving source %+v", s)
261						continue
262					}
263					if !reflect.DeepEqual(s.Path, wantPath) {
264						t.Errorf("source %q path = %v, want untouched %v", s.Root, s.Path, wantPath)
265					}
266				}
267	
268				if got := snap.ContentID; got != wantID {
269					t.Errorf("snapshot content id = %q, want %q", got, wantID)
270				}
271				if !reflect.DeepEqual(snap.Graph, wantGraph) {
272					t.Errorf("snapshot graph moved:\n got %#v\nwant %#v", snap.Graph, wantGraph)
273				}
274				if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, wantBytes) {
275					t.Errorf("snapshot export moved:\n got %s\nwant %s", got, wantBytes)
276				}
277				names := map[string]bool{}
278				for _, ds := range snap.Graph.Datasets {
279					names[ds.Name] = true
280				}
281				for _, want := range []string{"D", "E", "P", "Q", "M", "R1", "R2"} {
282					if !names[want] {
283						t.Errorf("snapshot lost dataset %q after a sources-array edit", want)
284					}
285				}
286				if got := mustSnapshotDataset(t, snap, "R1").Upstreams; len(got) != 0 {
287					t.Errorf("snapshot R1.upstreams = %v, want frozen empty", got)
288				}
289				if got := mustSnapshotDataset(t, snap, "R2").Upstreams; len(got) != 0 {
290					t.Errorf("snapshot R2.upstreams = %v, want frozen empty", got)
291				}
292			})
293		}
294	}
