296	// TestTraceTwoReportsOfSameSnapshotAreIndependent pins that two reports
297	// obtained successively from one snapshot — same query, then a different
298	// downstream that passes through the SAME intermediate dataset — start
299	// equal, but editing one leaves the other still representing the result as
300	// of when it was taken. After the edits, re-querying the original dataset
301	// still returns the snapshot's original sources and paths.
302	func TestTraceTwoReportsOfSameSnapshotAreIndependent(t *testing.T) {
303		snap := snapshotOf(t, traceSharedIntermediateJSON)
304		wantID := snap.ContentID
305		wantBytes := mustMarshalSnapshot(t, snap)
306	
307		first, err := TraceSources(snap, "D")
308		if err != nil {
309			t.Fatalf("first TraceSources: %v", err)
310		}
