327		}
328		if !reflect.DeepEqual(first.Sources, wantD) || !reflect.DeepEqual(second.Sources, wantD) {
329			t.Fatalf("initial D reports = %+v / %+v, want %+v", first.Sources, second.Sources, wantD)
330		}
331		if !reflect.DeepEqual(otherDownstream.Sources, wantE) {
332			t.Fatalf("E report = %+v, want %+v", otherDownstream.Sources, wantE)
333		}
334		secondJSON := traceReportJSON(t, second)
335		otherJSON := traceReportJSON(t, otherDownstream)
336	
337		// Edit the first report exhaustively: both path names in place, append
338		// onto the path, rename the root, reorder, and remove the second record.
339		s1 := sourceByRoot(first, "R1")
340		s1.Path[0] = "QUERY-X"
341		s1.Path[1] = "MID-X"
342		s1.Path = append(s1.Path, "TAIL-X")
343		s1.Root = "ROOT-X"
344		first.Sources[1].Root = "ROOT-Y"
345		first.Sources[0], first.Sources[1] = first.Sources[1], first.Sources[0]
346		first.Dataset = "EDITED"
