356			t.Errorf("second report R1 path = %v, want [D M R1]", got)
357		}
358		if got := sourceByRoot(second, "R2").Path; !reflect.DeepEqual(got, []string{"D", "P", "M", "R2"}) {
359			t.Errorf("second report R2 path = %v, want [D M R2]", got)
360		}
361		if got := sourceByRoot(otherDownstream, "R1").Path; !reflect.DeepEqual(got, []string{"E", "Q", "M", "R1"}) {
362			t.Errorf("E report R1 path = %v, want [E M R1]", got)
363		}
364		if got := traceReportJSON(t, otherDownstream); !bytes.Equal(got, otherJSON) {
365			t.Errorf("E report changed after the D report was edited:\n got %s\nwant %s", got, otherJSON)
366		}
367	
368		// Re-query after the edits: the snapshot answers with the original
369		// sources and paths, content id and queried name correct.
370		again, err := TraceSources(snap, "D")
371		if err != nil {
372			t.Fatalf("re-query TraceSources: %v", err)
373		}
374		if !reflect.DeepEqual(again.Sources, wantD) {
375			t.Errorf("re-query Sources = %+v, want original %+v", again.Sources, wantD)
376		}
377		if got := again.ContentID; got != wantID {
378			t.Errorf("re-query ContentID = %q, want %q", got, wantID)
379		}
380		if got := again.Dataset; got != "D" {
381			t.Errorf("re-query Dataset = %q, want %q", got, "D")
382		}
383		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, wantBytes) {
384			t.Errorf("snapshot export changed after report edits/re-query:\n got %s\nwant %s", got, wantBytes)
385		}
386	}
387	
388	// TestTraceRootSingleElementPathIsIndependent pins the same independence for
389	// the minimal result: a root queried about itself gets a one-element path;
390	// editing it (in place, by append, by root rename) and removing the only
391	// record neither moves another report nor the snapshot, and a re-query still
392	// returns the single-element answer.
393	func TestTraceRootSingleElementPathIsIndependent(t *testing.T) {
394		snap := snapshotOf(t, traceSharedIntermediateJSON)
395		wantBytes := mustMarshalSnapshot(t, snap)
396	
397		first, err := TraceSources(snap, "R1")
398		if err != nil {
399			t.Fatalf("first TraceSources(R1): %v", err)
400		}
401		wantRoot := []SourceTrace{{Root: "R1", Path: []string{"R1"}}}
402		if !reflect.DeepEqual(first.Sources, wantRoot) {
403			t.Fatalf("Sources = %+v, want %+v", first.Sources, wantRoot)
404		}
405		second, err := TraceSources(snap, "R1")
406		if err != nil {
407			t.Fatalf("second TraceSources(R1): %v", err)
408		}
409		secondJSON := traceReportJSON(t, second)
410	
411		// Overwrite the single name in place, append a tail, rename the root,
412		// then drop the only record entirely.
413		first.Sources[0].Path[0] = "SELF-X"
414		if sourceByRoot(second, "R1") == nil {
415			t.Fatalf("second report lost its record before any edit reached it")
416		}
417		if got := sourceByRoot(second, "R1").Path; !reflect.DeepEqual(got, []string{"R1"}) {
418			t.Errorf("second report path = %v, want [R1]", got)
419		}
420		first.Sources[0].Path = append(first.Sources[0].Path, "TAIL-X")
421		first.Sources[0].Root = "ROOT-X"
422		if got := traceReportJSON(t, second); !bytes.Equal(got, secondJSON) {
423			t.Errorf("second root report changed:\n got %s\nwant %s", got, secondJSON)
424		}
425		first.Sources = first.Sources[:0]
426	
427		again, err := TraceSources(snap, "R1")
428		if err != nil {
429			t.Fatalf("re-query TraceSources(R1): %v", err)
430		}
431		if !reflect.DeepEqual(again.Sources, wantRoot) {
432			t.Errorf("re-query Sources = %+v, want %+v", again.Sources, wantRoot)
433		}
434		if got := again.ContentID; got != snap.ContentID {
435			t.Errorf("re-query ContentID = %q, want %q", got, snap.ContentID)
436		}
437		if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, wantBytes) {
438			t.Errorf("snapshot export moved:\n got %s\nwant %s", got, wantBytes)
439		}
440	}
441	
442	// TestTraceFailedFollowUpQueriesKeepPriorReportAndSnapshot pins the error
443	// boundary around a held success report: while that report is retained,
444	// querying an empty name or a name absent from the snapshot must fail with
445	// the existing error categories, return no usable report, and leave the
446	// earlier success report and the input snapshot exactly as they were.
447	func TestTraceFailedFollowUpQueriesKeepPriorReportAndSnapshot(t *testing.T) {
448		snap := snapshotOf(t, traceSharedIntermediateJSON)
449		wantBytes := mustMarshalSnapshot(t, snap)
450	
451		prior, err := TraceSources(snap, "D")
452		if err != nil {
453			t.Fatalf("prior TraceSources: %v", err)
454		}
455		priorJSON := traceReportJSON(t, prior)
456		wantSources := []SourceTrace{
457			{Root: "R1", Path: []string{"D", "P", "M", "R1"}},
458			{Root: "R2", Path: []string{"D", "P", "M", "R2"}},
459		}
460	
461		for _, tc := range []struct {
462			name    string
463			dataset string
464			wantErr error
465		}{
466			{"empty name", "", ErrInvalidArgument},
467			{"unknown name", "ghost", ErrNotFound},
468		} {
469			t.Run(tc.name, func(t *testing.T) {
470				bad, err := TraceSources(snap, tc.dataset)
471				if !errors.Is(err, tc.wantErr) {
472					t.Fatalf("TraceSources(%q) err = %v, want %v", tc.dataset, err, tc.wantErr)
473				}
474				if bad != nil {
475					t.Fatalf("failed query returned a usable report: %#v", bad)
476				}
477				if got := traceReportJSON(t, prior); !bytes.Equal(got, priorJSON) {
478					t.Errorf("prior success report moved after a failed query:\n got %s\nwant %s", got, priorJSON)
479				}
480				if !reflect.DeepEqual(prior.Sources, wantSources) {
481					t.Errorf("prior Sources = %+v, want %+v", prior.Sources, wantSources)
482				}
483				if got := prior.ContentID; got != snap.ContentID {
484					t.Errorf("prior ContentID = %q, want %q", got, snap.ContentID)
485				}
486				if got := mustMarshalSnapshot(t, snap); !bytes.Equal(got, wantBytes) {
487					t.Errorf("snapshot export moved after failed query:\n got %s\nwant %s", got, wantBytes)
488				}
489			})
490		}
491	}
492	
493	// TestTraceIndependencePreservesBusinessRulesAndVerbatimNames checks that the
494	// reports the independence tests rely on still follow every selection rule
495	// and preserve Chinese characters, casing, and surrounding spaces verbatim
496	// inside independently owned slices. Editing one path must not normalize,
497	// trim, case-fold, or re-sort anything in another record.
498	func TestTraceIndependencePreservesBusinessRulesAndVerbatimNames(t *testing.T) {
499		// Two roots " A " (leading/trailing space, byte 0x20) and "根" reachable
500		// via one intermediate; a second path to " A " of equal length through a
501		// bytewise-larger intermediate loses the tie-break at position 1.
502		//
503		//	D -> M -> " A "
504		//	D -> z -> " A "
505		//	D -> M -> "根"
506		graphJSON := `{"datasets":[
507			{"name":"D","upstreams":["z","M"]},
508			{"name":"M","upstreams":["根"," A "]},
509			{"name":"z","upstreams":[" A "]},
510			{"name":" A ","upstreams":[]},
511			{"name":"根","upstreams":[]}
512		]}`
513		snap := snapshotOf(t, graphJSON)
514		report := traceOf(t, graphJSON, "D")
515	
516		// Every root exactly once; " A " (0x20...) sorts before "根" (0xE8...) by
517		// UTF-8 byte order; the equal-length choice to " A " is via M (0x4D <
518		// 0x7A), decided element by element from the query end.
519		want := []SourceTrace{
520			{Root: " A ", Path: []string{"D", "M", " A "}},
521			{Root: "根", Path: []string{"D", "M", "根"}},
522		}
523		if !reflect.DeepEqual(report.Sources, want) {
524			t.Fatalf("Sources = %+v, want %+v", report.Sources, want)
525		}
526	
527		// Edit the " A " path; the Chinese-named root record and the snapshot
528		// stay verbatim.
529		s := sourceByRoot(report, " A ")
530		s.Path[2] = " A-X"
531		s.Path = append(s.Path, "  ")
532		report.Sources[0].Root = " 根 "
533	
534		if got := sourceByRoot(report, "根"); got == nil {
535			t.Fatalf("Chinese-named root record lost after editing the other path")
536		} else if wantRec := (SourceTrace{Root: "根", Path: []string{"D", "M", "根"}}); !reflect.DeepEqual(*got, wantRec) {
537			t.Errorf("根 record = %+v, want untouched %+v", *got, wantRec)
538		}
539		if got := mustSnapshotDataset(t, snap, " A ").Name; got != " A " {
540			t.Errorf("snapshot root name = %q, want verbatim %q", got, " A ")
541		}
542		if got := mustSnapshotDataset(t, snap, "根").Name; got != "根" {
543			t.Errorf("snapshot root name = %q, want verbatim %q", got, "根")
544		}
545		if got := mustSnapshotDataset(t, snap, "M").Upstreams; !reflect.DeepEqual(got, []string{" A ", "根"}) {
546			t.Errorf("snapshot M.upstreams = %v, want verbatim frozen [\" A \" 根]", got)
547		}
548	}
